-- تقسیمات کشوری ایران -- سال 1397
-- https://github.com/Hameds/IranCountryDivisions
--
-- این فایل مخصوص Microsoft SQL Server است: ستون‌ها NVARCHAR و مقادیر با پیشوند N
-- تا حروف فارسی مستقل از collation دیتابیس درست ذخیره شوند.
-- فایل با کدگذاری UTF-8 ذخیره شده؛ برای اجرا با sqlcmd از سوییچ -f 65001 استفاده کنید.
--
-- DivisionType: 0 کشور، 1 استان، 2 شهرستان، 3 بخش، 4 دهستان،
--               5 شهر، 6 آبادی، 7 منطقه شهری
-- عمق در درخت از زنجیره ParentCountryDivisionId گرفته می‌شود، نه از DivisionType.

IF OBJECT_ID('dbo.CountryDivisions', 'U') IS NOT NULL
    DROP TABLE dbo.CountryDivisions;
GO

CREATE TABLE dbo.CountryDivisions (
    Id                      INT           NOT NULL,
    ParentCountryDivisionId INT               NULL,
    Name                    NVARCHAR(150) NOT NULL,
    Code                    NVARCHAR(10)  NOT NULL,
    DivisionType            TINYINT       NOT NULL,
    CONSTRAINT PK_CountryDivisions PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT FK_CountryDivisions_Parent
        FOREIGN KEY (ParentCountryDivisionId) REFERENCES dbo.CountryDivisions (Id)
);
GO

